//! Python/Rust parity (golden vector generated by `scripts/gen_golden_vector.py`
//! from the hub-api reference primitives) and end-to-end `TenantCrypto`
//! behaviour with a fake provider: round trip, cross-tenant/community/key
//! failure, rotation, and fail-closed key unavailability.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};

use aes_gcm::aead::generic_array::GenericArray;
use bundle_host_crypto::envelope::{
    blind_index_with_subkey, build_aad, derive_subkey, envelope_dek_version, open_with_subkey,
    seal_with_nonce, Purpose,
};
use bundle_host_crypto::{CryptoError, Dek, DekProvider, DekUnavailableError, TenantCrypto};
use zeroize::Zeroizing;

fn vector() -> serde_json::Value {
    serde_json::from_str(include_str!("fixtures/golden_vector.json"))
        .unwrap_or_else(|e| panic!("fixture parses: {e}"))
}

fn hex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap_or_else(|e| panic!("hex: {e}")))
        .collect()
}

fn text<'a>(v: &'a serde_json::Value, k: &str) -> &'a str {
    v[k].as_str().unwrap_or_else(|| panic!("missing {k}"))
}

fn strings(v: &serde_json::Value, k: &str) -> Vec<String> {
    v[k].as_array()
        .unwrap_or_else(|| panic!("missing {k}"))
        .iter()
        .map(|x| x.as_str().unwrap_or_default().to_string())
        .collect()
}

fn dek_arr(v: &serde_json::Value) -> [u8; 32] {
    hex(text(v, "dek_hex"))
        .try_into()
        .unwrap_or_else(|_| panic!("dek is 32 bytes"))
}

#[test]
fn golden_vector_matches_python_reference() {
    let v = vector();
    let dek = dek_arr(&v);
    let tenant = text(&v, "tenant_id");
    let version = v["dek_version"].as_u64().unwrap_or_default() as u32;
    let parts = strings(&v, "aad_parts");
    let parts: Vec<&str> = parts.iter().map(String::as_str).collect();

    let subkey = derive_subkey(&dek, tenant, Purpose::Data).unwrap_or_else(|e| panic!("{e}"));
    assert_eq!(&subkey[..], &hex(text(&v, "data_subkey_hex"))[..]);

    let nonce_bytes = hex(text(&v, "nonce_hex"));
    let sealed = seal_with_nonce(
        &subkey,
        version,
        &build_aad(&parts, version),
        &hex(text(&v, "plaintext_hex")),
        *GenericArray::from_slice(&nonce_bytes),
    )
    .unwrap_or_else(|e| panic!("{e}"));
    assert_eq!(sealed, hex(text(&v, "envelope_hex")));

    // Opening the Python-produced envelope recovers the plaintext.
    let opened = open_with_subkey(
        &subkey,
        &hex(text(&v, "envelope_hex")),
        &build_aad(&parts, version),
    )
    .unwrap_or_else(|e| panic!("{e}"));
    assert_eq!(opened, hex(text(&v, "plaintext_hex")));
}

#[test]
fn golden_vector_detects_a_flipped_byte() {
    let v = vector();
    let dek = dek_arr(&v);
    let version = v["dek_version"].as_u64().unwrap_or_default() as u32;
    let parts = strings(&v, "aad_parts");
    let parts: Vec<&str> = parts.iter().map(String::as_str).collect();
    let subkey =
        derive_subkey(&dek, text(&v, "tenant_id"), Purpose::Data).unwrap_or_else(|e| panic!("{e}"));
    let mut env = hex(text(&v, "envelope_hex"));
    let last = env.len() - 1;
    env[last] ^= 0x01;
    assert!(matches!(
        open_with_subkey(&subkey, &env, &build_aad(&parts, version)),
        Err(CryptoError::Integrity)
    ));
}

#[test]
fn blind_index_matches_python_reference() {
    let v = vector();
    let subkey = derive_subkey(&dek_arr(&v), text(&v, "tenant_id"), Purpose::BlindIndex)
        .unwrap_or_else(|e| panic!("{e}"));
    let ctx = strings(&v, "blind_context");
    let ctx: Vec<&str> = ctx.iter().map(String::as_str).collect();
    let got = blind_index_with_subkey(&subkey, &ctx, &hex(text(&v, "blind_value_hex")))
        .unwrap_or_else(|e| panic!("{e}"));
    assert_eq!(got.to_vec(), hex(text(&v, "blind_index_hex")));
}

type DekMap = HashMap<(String, u32), [u8; 32]>;

/// Fake provider: per-tenant DEKs, an active version, retired versions, and
/// a kill switch to simulate broker outage.
#[derive(Clone)]
struct Fake {
    deks: Arc<Mutex<DekMap>>,
    active: Arc<Mutex<HashMap<String, u32>>>,
}

impl Fake {
    fn new() -> Self {
        Self {
            deks: Arc::new(Mutex::new(HashMap::new())),
            active: Arc::new(Mutex::new(HashMap::new())),
        }
    }
    fn put(&self, tenant: &str, version: u32, byte: u8, make_active: bool) {
        if let Ok(mut d) = self.deks.lock() {
            d.insert((tenant.to_string(), version), [byte; 32]);
        }
        if make_active {
            if let Ok(mut a) = self.active.lock() {
                a.insert(tenant.to_string(), version);
            }
        }
    }
    fn err(tenant: &str, version: Option<u32>) -> DekUnavailableError {
        DekUnavailableError {
            tenant_id: tenant.to_string(),
            dek_version: version,
            reason: "unknown".to_string(),
        }
    }
}

impl DekProvider for Fake {
    async fn get_dek(&self, tenant_id: &str) -> Result<(Dek, u32), DekUnavailableError> {
        let version = self
            .active
            .lock()
            .ok()
            .and_then(|a| a.get(tenant_id).copied())
            .ok_or_else(|| Self::err(tenant_id, None))?;
        let key = self
            .deks
            .lock()
            .ok()
            .and_then(|d| d.get(&(tenant_id.to_string(), version)).copied())
            .ok_or_else(|| Self::err(tenant_id, Some(version)))?;
        Ok((Zeroizing::new(key), version))
    }

    async fn get_dek_version(
        &self,
        tenant_id: &str,
        version: u32,
    ) -> Result<Dek, DekUnavailableError> {
        self.deks
            .lock()
            .ok()
            .and_then(|d| d.get(&(tenant_id.to_string(), version)).copied())
            .map(Zeroizing::new)
            .ok_or_else(|| Self::err(tenant_id, Some(version)))
    }
}

const AAD: [&str; 5] = ["1", "2", "app.a", "kv", "k1"];

#[tokio::test]
async fn round_trip_and_ciphertext_hides_plaintext() {
    let f = Fake::new();
    f.put("1", 1, 9, true);
    let c = TenantCrypto::new(f);
    let sealed = c
        .seal("kv", "1", &AAD, b"top-secret-value")
        .await
        .unwrap_or_else(|e| panic!("{e}"));
    assert!(TenantCrypto::is_sealed(&sealed));
    assert!(!sealed.windows(10).any(|w| w == b"top-secret"));
    let opened = c
        .open("kv", "1", &AAD, &sealed)
        .await
        .unwrap_or_else(|e| panic!("{e}"));
    assert_eq!(opened, b"top-secret-value");
}

#[tokio::test]
async fn cross_tenant_community_app_and_key_swaps_fail() {
    let f = Fake::new();
    f.put("1", 1, 9, true);
    f.put("2", 1, 8, true);
    let c = TenantCrypto::new(f);
    let sealed = c
        .seal("kv", "1", &AAD, b"v")
        .await
        .unwrap_or_else(|e| panic!("{e}"));
    // Other tenant (different DEK and different AAD).
    assert!(c.open("kv", "2", &AAD, &sealed).await.is_err());
    // Same tenant, different community / app / key.
    for aad in [
        ["1", "3", "app.a", "kv", "k1"],
        ["1", "2", "app.b", "kv", "k1"],
        ["1", "2", "app.a", "kv", "k2"],
    ] {
        assert!(matches!(
            c.open("kv", "1", &aad, &sealed).await,
            Err(CryptoError::Integrity)
        ));
    }
}

#[tokio::test]
async fn rotation_reads_old_and_new_and_unknown_version_fails_closed() {
    let f = Fake::new();
    f.put("1", 1, 9, true);
    let c = TenantCrypto::new(f.clone());
    let old = c
        .seal("kv", "1", &AAD, b"old")
        .await
        .unwrap_or_else(|e| panic!("{e}"));
    f.put("1", 2, 7, true);
    let new = c
        .seal("kv", "1", &AAD, b"new")
        .await
        .unwrap_or_else(|e| panic!("{e}"));
    assert_eq!(envelope_dek_version(&old).unwrap_or(0), 1);
    assert_eq!(envelope_dek_version(&new).unwrap_or(0), 2);
    assert_eq!(
        c.open("kv", "1", &AAD, &old).await.unwrap_or_default(),
        b"old"
    );
    assert_eq!(
        c.open("kv", "1", &AAD, &new).await.unwrap_or_default(),
        b"new"
    );

    // A version the provider has never heard of: fail closed.
    let mut forged = new.clone();
    forged[5..9].copy_from_slice(&9u32.to_be_bytes());
    assert!(matches!(
        c.open("kv", "1", &AAD, &forged).await,
        Err(CryptoError::KeyUnavailable(_))
    ));
}

#[tokio::test]
async fn missing_key_refuses_seal_and_open() {
    let f = Fake::new();
    f.put("1", 1, 9, true);
    let c = TenantCrypto::new(f);
    assert!(matches!(
        c.seal("kv", "404", &AAD, b"x").await,
        Err(CryptoError::KeyUnavailable(_))
    ));
    let sealed = c
        .seal("kv", "1", &AAD, b"x")
        .await
        .unwrap_or_else(|e| panic!("{e}"));
    assert!(matches!(
        c.open("kv", "404", &AAD, &sealed).await,
        Err(CryptoError::KeyUnavailable(_) | CryptoError::Integrity)
    ));
}

#[tokio::test]
async fn nonces_are_fresh_per_seal() {
    let f = Fake::new();
    f.put("1", 1, 9, true);
    let c = TenantCrypto::new(f);
    let a = c.seal("kv", "1", &AAD, b"same").await.unwrap_or_default();
    let b = c.seal("kv", "1", &AAD, b"same").await.unwrap_or_default();
    assert_ne!(a, b);
}

#[tokio::test]
async fn legacy_plaintext_is_not_an_envelope() {
    let f = Fake::new();
    f.put("1", 1, 9, true);
    let c = TenantCrypto::new(f);
    assert!(!TenantCrypto::is_sealed(b"{\"plain\":true}"));
    assert!(matches!(
        c.open("kv", "1", &AAD, b"{\"plain\":true}").await,
        Err(CryptoError::NotEnvelope)
    ));
}
